import pathlib,json,datetime,html,hashlib
R=pathlib.Path('.');D='2026-10-27';NOW=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat()
def load(p):return json.loads((R/p).read_text(encoding='utf-8-sig'))
def save(p,x):
 p=R/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
r=load(f'docs/daily-reports/{D}.json');over=load('src/data/i18n/en-overrides.json');photos={p['key']:p for p in load(f'docs/image-licenses/{D}.json')}
def t(a,b):
 over[a]=b
 if a.startswith('#'):over[a.lstrip('# ')]=b.lstrip('# ')
 return a
def photo(k):
 p=photos[k];names={'ca':('Western University校園資料照','Archive photograph of Western University campus'),'de':('Freiburg大學Kollegiengebäude I資料照','Archive photograph of Kollegiengebaeude I at the University of Freiburg'),'au':('雪梨大學Quadrangle校園資料照','Archive photograph of the University of Sydney Quadrangle'),'bluegrass':('肯塔基大學北校區資料照','Archive photograph of University of Kentucky North Campus'),'presidential':('肯塔基大學Margaret I King圖書館資料照','Archive photograph of Margaret I King Library at the University of Kentucky'),'singletary':('肯塔基大學Memorial Hall資料照','Archive photograph of Memorial Hall at the University of Kentucky'),'diy':('肯塔基大學圖書館資料照','Archive photograph of the University of Kentucky library'),'taiwan':('國立臺灣大學校園資料照','Archive photograph of National Taiwan University campus'),'peter':('Huron University圖書館閱讀空間資料照','Archive photograph of a reading area at Huron University Library')}
 return dict(image='/'+p['file'].removeprefix('public/'),imageAlt=t(*names[k]),imageCredit=p['author']+' / '+p['license']+'; cropped',imageSource=p['source'],imageLicense=p['license'])
def md(path,fm,pairs,key):
 p=R/path;assert not p.exists(),path
 p.write_text('---\n'+''.join(k+': '+json.dumps(v,ensure_ascii=False)+'\n' for k,v in fm.items())+'---\n\n'+'\n\n'.join(t(a,b) for a,b in pairs)+f'\n\n[Photo attribution and adaptation license](/images/daily/{D}/credits.html#{key})\n',encoding='utf8')
 for suf,eng in [('｜環球教育新聞網 Global Education News',' | Global Education News'),('｜台灣國際獎學金雷達',' | Taiwan Global Scholarship Radar')]:over[fm['title']+suf]=over[fm['title']]+eng
U={'ca':'https://news.westernu.ca/2026/10/immunequity-2/','ca-second':'https://www.cbc.ca/news/canada/london/western-university-research-to-develop-hiv-cure-receives-24m-in-federal-funds-9.7393176','au':'https://mixabroad.com/mixagent/','au-second':'https://thepienews.com/australian-universities-back-new-benchmark-for-education-agents/','de':'https://www.wissenschaftsrat.de/SharedDocs/Pressemitteilungen/EN/PM_2126_ExStra_EN','de-second':'https://sign-network.eu/news/2026_10_06_WDR_cosmo-italiano_universities_of_excellence/','awards':'https://studentsuccess.uky.edu/financial-aid-and-scholarships/academic-scholarships/incoming-freshmen-scholarships','faq':'https://studentsuccess.uky.edu/financial-aid-and-scholarships/academic-scholarships/academic-scholarship-faq','apply':'https://international.uky.edu/apply','bluegrass-second':'https://borderless.so/scholarships/university-of-kentucky/bluegrass-scholarship','presidential-second':'https://borderless.so/scholarships/university-of-kentucky/presidential-scholarship','singletary-second':'https://borderless.so/scholarships/university-of-kentucky/otis-a-singletary-scholarship'}
news=[];sch=[]
def article(slug,title,en,desc,de,key,topic,pairs):
 sources=[dict(label='Primary source',url=U[key]),dict(label='Independent cross-check',url=U[key+'-second'])];path='src/pages/news/'+slug+'.md'
 md(path,dict(layout='../../layouts/ArticleLayout.astro',title=t(title,en),description=t(desc,de),date=NOW,author='LTU Global Education News 編輯部',category=t('國際教育新聞','International education news'),topic=topic,tags=[topic,'Research','2026'],**photo(key),sources=sources),pairs,key)
 news.append(dict(slug=slug,title=title,url='https://globalednews.com/news/'+slug+'/',publishedPath=path,sources=sources,verifiedAt=NOW))
article('canada-uganda-immunequity-research-2026','加拿大Western獲2,400萬加元：串聯烏干達與跨校HIV研究','Western receives CAD24 million for Canada–Uganda HIV research collaboration','六年IMMUNEQUITY研究結合加拿大與烏干達團隊；資助研究目標不等於已證實療法，也不是招生或獎學金公告。','The six-year IMMUNEQUITY collaboration brings together Canadian and Ugandan teams; funding does not establish a proven treatment or an admission offer.','ca','canada',[
('## 以跨國合作推進研究','## Research through international collaboration'),('Western University於10月23日說明，IMMUNEQUITY團隊獲加拿大聯邦2,400萬加元資助，規劃六年研究。合作網絡包括Western、UBC、Ottawa、Montréal與Manitoba等加拿大大學，以及烏干達Joint Clinical Research Centre與Makerere University。CBC同日報導並採訪研究團隊，核對資助規模與跨國合作方向。','Western University reported on October 23 that IMMUNEQUITY received CAD24 million in federal funding for a six-year project. Partners include Western, UBC, Ottawa, Montreal and Manitoba in Canada, alongside Uganda’s Joint Clinical Research Centre and Makerere University. CBC independently reported the funding and interviewed the researchers.'),
('## 研究目標與現階段成果要分開','## Separate the research aim from an established result'),('計畫把治療研發、生物製造與可負擔性放在同一研究架構，目標包括在加拿大與烏干達推進首次人體研究。這是待完成的研發目標，不能寫成已找到可普遍使用的HIV治癒方法，也不能將經費總額解讀為學生可直接申請的獎學金。','The program links therapeutic development, biomanufacturing and affordability, aiming to advance first-in-human studies in Canada and Uganda. These are research objectives, not evidence of a broadly available HIV cure. The project’s funding is not a scholarship pool open directly to students.'),
('## 台灣研究生可觀察什麼','## What prospective researchers can examine'),('對考慮生命科學、公共衛生或跨國研究的台灣學生，編輯部建議比較指導教師專長、合作機構、研究倫理訓練與實際課程。若希望加入相關團隊，仍須另查職缺、研究所招生與個別資助；不能因大型計畫成立就假設有保證名額。照片為Western校園資料照。','Taiwanese applicants interested in life sciences, public health or international research can compare supervisors, partners, ethics training and courses. Check vacancies, graduate admission and individual funding separately; a major project does not guarantee a student place. The image is an archive campus photograph.')])
article('australia-mixagent-student-feedback-2026','澳洲六家教育機構支持miXagent：用學生經驗檢視留學代辦','Six Australian education providers back miXagent student feedback benchmark','miXagent於10月推出，涵蓋申請到抵達的代辦經驗；參與者包括Navitas，不能全稱為六所大學。','Launched in October, miXagent surveys the agent journey from application to arrival; its six supporters include Navitas, not only universities.','au','australia',[
('## 六家機構共同參與','## Six participating providers'),('miXagent官方頁與The PIE於10月26日的報導指出，Edith Cowan、Griffith、Monash、Navitas、UNSW Sydney及University of Sydney支持這項新計畫。Navitas是教育服務提供者，因此正確說法為六家教育機構，而不是六所大學。','The miXagent page and The PIE’s October 26 report identify Edith Cowan, Griffith, Monash, Navitas, UNSW Sydney and the University of Sydney as supporters. Navitas is an education provider, so the group should not be described as six universities.'),
('## 用學生回饋補充品質管理','## Student feedback as an additional quality signal'),('計畫蒐集學生從選擇、申請到抵達期間的代辦經驗，建立可比較的回饋資訊。The PIE另採訪雪梨大學相關主管及Navitas，討論如何補充既有代辦管理。這是自願參與的評估機制，不是政府核發執照，也不是已公布的全澳代辦排名；目前不能據此列出「最佳代辦」。','The initiative gathers student experiences across decision-making, application and arrival to support comparison. The PIE interviews a University of Sydney representative and Navitas about its role alongside existing agent oversight. This voluntary benchmark is neither a government licence nor a published national ranking of the best agents.'),
('## 申請者仍須逐項核對','## Applicants still need a practical checklist'),('台灣家庭可把是否清楚揭露合作學校、費用、服務範圍與申請資料處理方式列入比較，也應直接向學校確認授權代辦名單。參加評估不等於保證錄取、簽證或服務結果；本文只報導計畫推出，不替個別業者背書。配圖為雪梨大學校園資料照。','Taiwanese families can compare partner-school disclosure, fees, service scope and handling of application materials, and check a university’s authorised-agent list directly. Participation does not guarantee admission, visas or service outcomes. This report describes the launch without endorsing individual agencies; the image shows the Sydney campus.')])
article('germany-excellence-universities-2027-funding','德國卓越策略新增五組：2027資助看研究條件，不等於錄取保證','Germany adds five Excellence groups: research funding starts in 2027','10月2日決定新增三所大學及兩個聯盟；連同十組續約共十五組，並非十五所獨立大學。','The October 2 decision adds three universities and two consortia; with ten renewals, the total is fifteen institutions or groups, not fifteen individual universities.','de','europe',[
('## 決定在10月，資助從2027年開始','## An October decision with funding from 2027'),('德國科學與人文委員會及DFG於10月2日公布卓越大學評選結果，從11份申請選出5組新增資助對象：Freiburg、Jena、Cologne三所大學，以及Rhine-Main Universities與Ruhr Innovation Lab兩個聯盟。本文整理已公布結果，不將其當作今天才宣布的消息；新資助自2027年1月開始。','The German Science and Humanities Council and DFG announced the selection on October 2: five of eleven applications succeeded. They are Freiburg, Jena and Cologne, plus the Rhine-Main Universities and Ruhr Innovation Lab consortia. This is a follow-up to the published decision, with funding starting in January 2027.'),
('## 聯盟與單校不能混算','## Count consortia and universities accurately'),('Rhine-Main由TU Darmstadt、Goethe Frankfurt與Johannes Gutenberg Mainz組成；Ruhr Innovation Lab包括Ruhr Bochum及TU Dortmund。連同十組延續資助者，共十五組機構或聯盟，並非十五所單獨大學。SIGN科學家網絡10月6日整理WDR節目討論，提供這項研究資助制度的外部脈絡。','Rhine-Main comprises TU Darmstadt, Goethe Frankfurt and Johannes Gutenberg Mainz; Ruhr Innovation Lab includes Ruhr Bochum and TU Dortmund. Together with ten renewals, there are fifteen funded institutions or consortia. The SIGN scientists’ network’s October 6 account of a WDR program provides independent context on the research-funding system.'),
('## 台灣學生仍要比較課程與指導','## Compare programs and supervision separately'),('卓越策略著重研究能力與制度發展，不是所有科系教學品質的統一排名。選校時應另查授課語言、學位要求、研究主題與指導安排；獎學金及入學申請須依個別公告辦理，不因卓越資格而自動取得。照片為Freiburg大學建築資料照。','The strategy supports research and institutional development; it is not a universal teaching-quality ranking. Compare course language, degree requirements, research fit and supervision. Admission and scholarships have separate applications. The image is an archive photograph of a Freiburg university building.')])
def scholarship(slug,title,en,key,amount,ae,pairs):
 assert slug not in r['scholarshipBaselineSlugs'];path='src/pages/scholarships/items/'+slug+'.md';sources=[dict(label='Official 2027 awards',url=U['awards']),dict(label='International eligibility FAQ',url=U['faq']),dict(label='Independent cross-check',url=U[key+'-second'])]
 fm=dict(layout='../../../layouts/ScholarshipLayout.astro',title=t(title,en),description=t('10月27日查核；適用符合條件的台灣籍2027秋季學士新生，12月1日前完整送件；三項不可疊加。','Reviewed October 27 for eligible Taiwanese first-year applicants entering fall 2027. Complete files are due December 1; the three awards cannot be combined.'),date=D,author='LTU Global Education News 編輯部',country=t('美國','United States'),level=t('學士','Bachelor'),funding=t(amount,ae),deadline='2026-12-01',status=t('開放中','Open'),sourceName='University of Kentucky / Borderless',officialUrl=U['awards'],secondSourceUrl=U[key+'-second'],eligibilityTW=t('可申請','Eligible to apply'),taiwanNote=t('國際新生可競逐學術及競爭性獎助；台灣學生須符合非州內身分、入學及各獎項條件，得獎不保證。','International first-year students may compete for academic and competitive awards. Taiwanese applicants must meet nonresident, admission and award-specific conditions; selection is not guaranteed.'),verificationDate=D,featuredDate=D,featuredUntil='2026-10-28T00:00:00+08:00',category=t('大學國際生獎學金','International undergraduate scholarships'),**photo(key))
 md(path,fm,pairs,key);sch.append(dict(slug=slug,title=title,url='https://globalednews.com/scholarships/items/'+slug+'/',publishedPath=path,sources=sources,verifiedAt=NOW,eligibleTaiwan=True,open=True,isNew=True,baselineAbsent=True,updateSummary='Distinct award, absent from 221-slug baseline. International eligibility and current Fall 2027 table checked; awards cannot stack.'))
common=[('## 台灣資格、截止與續領','## Eligibility, deadline and renewal'),('肯塔基大學FAQ明確開放國際生競逐學術及競爭性獎助；符合非州內新生資格的台灣申請者可申請。2027秋季入學與高中成績單等資料須於2026年12月1日前完整送達，經費可能提早用罄。所有金額以正式獎助信為準；本頁不把最低門檻當成保證獲獎。','The university FAQ explicitly permits international students to compete for academic and competitive awards. Eligible Taiwanese nonresident first-year applicants may apply. Fall 2027 admission documents, including transcripts, must arrive by December 1, 2026; funding may run out earlier. Minimum criteria do not guarantee an award.'),('## 三項獎助不可相加','## These three awards cannot be added together'),('官方2027新生專頁規定所列獎助只能領一項，競爭性獎助會取代學術獎助。Bluegrass、Presidential與Singletary是三個不同獎項，但不能累加估算預算；較舊的國際生簡介若出現不同敘述，以當期專頁及正式條款為準。','The current 2027 page limits recipients to one listed award; a competitive award replaces an academic award. Bluegrass, Presidential and Singletary are distinct awards, but cannot be added together when budgeting. Current terms supersede older general summaries.')]
scholarship('2026-10-kentucky-bluegrass-2027','肯塔基大學Bluegrass 2027：每年6,500至16,000美元學費獎助','Kentucky Bluegrass 2027: USD6,500–16,000 in annual tuition support','bluegrass','學費獎助每年USD 6,500–16,000','Annual tuition support of USD6,500–16,000',[
('## 錄取後自動評估，四級距算一項','## Automatic consideration, four tiers in one award'),('Bluegrass提供非州內學士新生每年6,500、10,000、13,000或16,000美元獎助。免測驗路徑的未加權GPA門檻分別為3.00、3.50、3.60及3.80；提交測驗的較高級距另有SAT／ACT組合，須依官方表格核對。錄取後自動評估，不須另填獎助表；本頁把四級距計為一項。','Bluegrass provides nonresident first-year students USD6,500, 10,000, 13,000 or 16,000 annually. Test-optional unweighted GPA thresholds are 3.00, 3.50, 3.60 and 3.80 respectively. Alternative SAT/ACT combinations appear in the official table. Admitted applicants receive automatic consideration without a separate award form; the tiers count as one scheme.'),
('## 續領不是自動延續','## Renewal has continuing requirements'),('四年可續領獎助須維持每學期至少12學分及累計GPA 3.0。這是部分學費支持，不包含全額住宿、餐食與交通；家庭應用淨學費加生活費估算四年支出。','The four-year renewable award requires at least 12 credits per semester and a cumulative GPA of 3.0. It provides partial tuition support, not full accommodation, food or travel. Budget using net tuition plus living expenses.')]+common)
scholarship('2026-10-kentucky-presidential-2027','肯塔基大學Presidential 2027：全額非州內學費，需競爭性審查','Kentucky Presidential 2027: full nonresident tuition through competitive selection','presidential','全額非州內學費與必要費用','Full nonresident tuition and mandatory fees',[
('## 高門檻與額外申請欄位','## Academic threshold and an additional application section'),('Presidential涵蓋全額非州內學費及必要費用。申請者須未加權GPA至少3.50並達ACT 31或SAT 1390，或免測驗路徑GPA 4.00；不得自行使用混合最高分取代官方要求。還須完成入學申請內的競爭性獎助欄位，名額有限，部分申請者可能獲邀面試。','Presidential covers full nonresident tuition and mandatory fees. Applicants need an unweighted GPA of at least 3.50 with ACT31 or SAT1390, or GPA4.00 through the test-optional route. Superscoring is not accepted. Complete the competitive scholarship section of the admission application; places are limited and interviews may be requested.'),
('## 全學費不等於全生活費','## Full tuition is not full living support'),('四年續領須每學期至少12學分及累計GPA 3.0。住宿、餐食與個人支出仍須另列預算，不應把Presidential寫成涵蓋所有留學成本。','Four-year renewal requires at least 12 semester credits and cumulative GPA3.0. Housing, food and personal expenses remain separate budget items; full tuition is not a promise to cover every study-abroad cost.')]+common)
scholarship('2026-10-kentucky-singletary-2027','肯塔基大學Singletary 2027：學費獎助加前兩年校內食宿津貼','Kentucky Singletary 2027: tuition support and an on-campus stipend for two years','singletary','全額非州內學費與費用；前兩年校內食宿津貼','Full nonresident tuition and fees; on-campus housing and dining stipend for two years',[
('## 獎助範圍與申請門檻','## Coverage and entry criteria'),('Otis A. Singletary涵蓋非州內學費、必要費用及課程／學程費用，另提供前兩年食宿津貼，但限居住校方宿舍者。不是四年全部生活費全包。門檻為未加權GPA至少3.80及ACT 33或SAT 1450，或免測驗路徑GPA 4.00；須完成入學申請中的競爭性獎助欄位，可能受邀面試。','Otis A. Singletary covers nonresident tuition, mandatory fees and course/program fees. A housing and dining stipend applies only during the first two years while living in a university residence hall. It is not four years of all living costs. Criteria are unweighted GPA3.80 with ACT33 or SAT1450, or test-optional GPA4.00. Complete the competitive application section; interviews may follow.'),
('## 續領成績門檻較高','## A higher renewal GPA'),('續領須維持全時學士身分、每學期至少12學分與累計GPA 3.40。申請前應分開估算前兩年與後兩年的住宿餐費，並保存正式獎助條款，不把其他獎項的GPA 3.0套用此獎。','Renewal requires full-time undergraduate enrolment, at least 12 credits each semester and cumulative GPA3.40. Budget separately for living costs in years one–two and three–four. Keep the award terms; the GPA3.0 rule for other awards does not apply here.')]+common)
diySlug='kentucky-first-year-scholarship-checklist-2027';diyTitle='肯塔基大學申請導航：自動評估與競爭性獎助分開準備';diyPath='src/pages/study-abroad/'+diySlug+'.md'
md(diyPath,dict(layout='../../layouts/ArticleLayout.astro',title=t(diyTitle,'Kentucky application checklist: automatic and competitive scholarships'),description=t('用一份申請清單分清送件、獎助欄位、四年預算與續領要求。','Separate admission documents, scholarship sections, four-year costs and renewal requirements.'),date=NOW,author='LTU Global Education News 編輯部',category=t('留學DIY導航','Study abroad DIY'),topic='usa',tags=['USA','Kentucky','2027'],**photo('diy'),sources=[dict(label='International application',url=U['apply']),dict(label='2027 awards',url=U['awards']),dict(label='Eligibility FAQ',url=U['faq'])]),[
('## 先建立完整入學檔案','## Start with a complete admission file'),('以University of Kentucky國際申請入口確認2027秋季學士新生流程，備妥學歷、英文能力與校方要求文件。獎助審查的12月1日期限包含高中成績單等支持資料，不能只在當天送出空白或不完整申請；經費可能提前用罄。','Use the University of Kentucky international admission portal to check the fall2027 first-year process and prepare academic, English and other required documents. The December1 scholarship deadline includes supporting records, not merely submission of an incomplete form. Funds may be exhausted earlier.'),
('## 自動評估與競爭申請分兩路','## Distinguish automatic and competitive routes'),('Bluegrass錄取後自動評估；Presidential與Singletary還須完成競爭性獎助欄位。先確認自己是否走測驗或免測驗路徑，再用未加權GPA及官方測驗規則核對。達門檻不代表得獎，也不能三項一起領。','Bluegrass uses automatic consideration after admission. Presidential and Singletary require the competitive scholarship section. Check the tested or test-optional route against unweighted GPA and official score rules. Meeting a threshold does not ensure selection, and the three awards cannot be combined.'),
('## 把續領與生活費一起算','## Budget for renewal and living costs'),('列出四年學費、住宿、餐食、保險與交通，再扣除正式核准獎助。Singletary食宿津貼限前兩年校內住宿，續領GPA也高於另外兩項。先查課程與學習支持，再從[留學DIY導航](/study-abroad/)比較其他學校，不單憑最高獎助額做決定。','List four years of tuition, housing, meals, insurance and travel, then deduct confirmed funding. Singletary’s living stipend is limited to the first two years on campus and has a higher renewal GPA. Compare programs and support through the [study abroad guide](/study-abroad/), rather than choosing solely by the largest advertised award.')],'diy')
peter=load('src/data/peter-articles.json');ps='learn-it-all-feedback-learning-log-2026';pu='https://www.facebook.com/photo/?fbid=122148270975172155&set=a.122101120425172155';assert not any(x.get('sourceId')=='122148270975172155' or x.get('slug')==ps for x in peter)
pt=t('別急著當Know-it-all：Peter談回饋、修正與學習紀錄','Beyond know-it-all: Peter on feedback, revision and a learning log');pe=t('從Nadella的學習文化觀點出發，把「繼續努力」變成可檢查的策略與證據。','Turn a learning-culture idea into specific strategies and evidence of revision.');pb=[
('Peter從Satya Nadella倡議的學習文化出發，提醒學生不必假裝自己什麼都懂。Microsoft官方Code Book把向他人學習、實驗及從錯誤調整列為文化方向；GeekWire於2016年報導Nadella相關訪談。這是長期觀點，不是Nadella今天對學生發表的新演說。','Peter draws on Satya Nadella’s learning-culture approach to encourage students to acknowledge gaps. Microsoft’s Code Book emphasises learning from others, experimentation and mistakes; GeekWire covered Nadella’s related interview in2016. This is a longstanding idea, not a new speech to students today.'),
('Peter建議把「我會更努力」換成具體行動：先用作品或測驗找出卡住之處，向老師、同學或導師取得可操作的回饋，再改變策略並重新檢查。例如英文簡報不只問好不好，而是請對方指出論點、證據或表達哪一部分需要調整。','Peter suggests replacing vague promises of more effort with a cycle: identify a gap in work, seek actionable feedback, change the approach and test again. For an English presentation, ask which argument, evidence or delivery needs revision rather than requesting a general rating.'),
('每週可以保留一份Learning Log，記下尚不理解的問題、可請教的人、下次嘗試的策略與進步證據。使用AI協助構思時，也要查來源、保留修改過程與自己的判斷。這是Peter的學習建議，不是能保證成績或錄取的研究結論。','A weekly learning log can record unresolved questions, people to consult, the next strategy and evidence of progress. When using AI for ideas, check sources and retain the revision process and personal judgement. These are Peter’s learning suggestions, not a guarantee of grades or admission.'),
('本篇經授權查核改寫粉專新文；10月27日查看時顯示「19小時前」，未取得精確發文時刻。配圖為Huron University圖書館授權資料照，並非Nadella或原貼文照片。','This authorised adaptation was checked against the new page post. On October27 it displayed “19 hours ago”; the exact publication time was unavailable. The licensed image shows Huron University Library, not Nadella or the original post.')]
